<?php

namespace App\Support\EcomxAnyniche;

/**
 * File-backed (no DB) registry of per-page SEO fields (meta title/description/OG image).
 * Storage: storage/app/private/themes/{active theme}/page-seo.json — see
 * ActiveTheme::storagePath(). Git-ignored admin state, generated by
 * syncAllPages() ("Sync all pages" in the admin).
 * Mirrors PageSectionRegistry's read/write pattern (flock + atomic rename).
 */
class PageSeoRegistry
{
    protected static function path(): string
    {
        return ActiveTheme::storagePath('page-seo.json');
    }

    protected static function read(): array
    {
        $path = static::path();

        if (! file_exists($path)) {
            return [];
        }

        $handle = fopen($path, 'r');
        if ($handle === false) {
            return [];
        }

        try {
            flock($handle, LOCK_SH);
            $contents = stream_get_contents($handle);
        } finally {
            flock($handle, LOCK_UN);
            fclose($handle);
        }

        $data = json_decode($contents, true);

        return is_array($data) ? $data : [];
    }

    protected static function write(array $data): void
    {
        $path = static::path();
        $dir = dirname($path);

        if (! is_dir($dir)) {
            mkdir($dir, 0755, true);
        }

        $tmp = $path . '.' . uniqid('', true) . '.tmp';
        file_put_contents($tmp, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
        rename($tmp, $path);
    }

    /** Whether page-seo.json has been generated yet (see syncAllPages()). */
    public static function isGenerated(): bool
    {
        return file_exists(static::path());
    }

    /** SEO fields for a page: meta_title, meta_description, og_image. */
    public static function forPage(string $page): array
    {
        return array_merge([
            'meta_title' => '',
            'meta_description' => '',
            'og_image' => '',
        ], static::read()[$page] ?? []);
    }

    public static function save(string $page, array $fields): void
    {
        $data = static::read();
        $data[$page] = array_merge($data[$page] ?? [], array_intersect_key(
            $fields,
            array_flip(['meta_title', 'meta_description', 'og_image'])
        ));

        static::write($data);
    }

    /**
     * Writes an empty SEO entry into page-seo.json for every config-declared
     * page not already present, so every page has a visible, editable row
     * from the moment it's registered — forPage() already tolerates a
     * missing entry via its defaults, so this is purely for admin
     * discoverability/consistency with PageSectionRegistry::syncAllPages(),
     * not a functional requirement. Never touches a page that already has
     * saved SEO fields.
     *
     * @return string[] Page keys that were newly seeded by this call.
     */
    public static function syncAllPages(): array
    {
        $data = static::read();
        $seeded = [];

        foreach (PageRegistry::all() as $page => $meta) {
            if (array_key_exists($page, $data)) {
                continue;
            }

            $data[$page] = [
                'meta_title' => '',
                'meta_description' => '',
                'og_image' => '',
            ];
            $seeded[] = $page;
        }

        if ($seeded !== [] || ! static::isGenerated()) {
            static::write($data);
        }

        return $seeded;
    }
}
